input.command:
$content = Get-Content -Path "g:\0.CMS-MAIN-ALL -ctt\qunagr binhup pdf\New folder\content.txt" -Raw

# Extract header (first 2 lines)
$lines = $content -split "`r`n|`n"
$header = $lines[0] -join "`r`n"
$header = $lines[0] + "`r`n" + $lines[1]

# Extract footer (last 2 lines)
$footer = $lines[-2] + "`r`n" + $lines[-1]

# Extract all <a> tags
$pattern = '<a href="/Media/quy-trinh/QT[^"]*" style="[^"]*">[^<]*</a>'
$matches = [regex]::Matches($content, $pattern)

# Build objects with QT number for sorting
$linkObjects = @()
foreach ($match in $matches) {
    $href = $match.Value

    # Extract QT number from href
    if ($href -match '/Media/quy-trinh/QT\s*(\d+)') {
        $qtNum = [int]$matches[1].Value
    } elseif ($href -match '/Media/quy-trinh/QT0*(\d+)') {
        $qtNum = [int]$matches[1].Value
    } elseif ($href -match '/Media/quy-trinh/QT\.\s*0*(\d+)') {
        $qtNum = [int]$matches[1].Value
    } else {
        $qtNum = 999
    }

    $linkObjects += [PSCustomObject]@{
        QTNum = $qtNum
        Link = $href
    }
}

# Sort by QT number then by filename for same numbers
$sorted = $linkObjects | Sort-Object QTNum

# Build output
$output = $header + "`r`n"
foreach ($item in $sorted) {
    $output += $item.Link + "`r`n"
}
$output += $footer

# Write back
$output | Out-File -FilePath "g:\0.CMS-MAIN-ALL -ctt\qunagr binhup pdf\New folder\content.txt" -Encoding UTF8

Write-Host "Done! Sorted $($sorted.Count) links by QT number"

$content = Get-Content -Path "g:\0.CMS-MAIN-ALL -ctt\qunagr binhup pdf\New folder\content.txt" -Raw

$lines = $content -split "`r`n|`n"
$header = $lines[0] + "`r`n" + $lines[1]
$footer = $lines[-1]
if ($lines[-2] -match "</div>") { $footer = $lines[-2] + "`r`n" + $lines[-1] }

$pattern = '<a href="/Media/quy-trinh/QT[^"]*" style="[^"]*">[^<]*</a>'
$matches = [regex]::Matches($content, $pattern)

$linkObjects = @()
foreach ($m in $matches) {
    $href = $m.Value
    $num = 0

    # Extract number from href like QT01, QT 06, QT. 03, QT05, QT 18_, QT18
    if ($href -match '/Media/quy-trinh/QT\s*(\d+)') {
        $num = [int][regex]::Match($href, '/Media/quy-trinh/QT\s*(\d+)').Groups[1].Value
    } elseif ($href -match '/Media/quy-trinh/QT\.\s*(\d+)') {
        $num = [int][regex]::Match($href, '/Media/quy-trinh/QT\.\s*(\d+)').Groups[1].Value
    }

    $linkObjects += [PSCustomObject]@{ QTNum = $num; Link = $href }
}

$sorted = $linkObjects | Sort-Object QTNum

$output = $header + "`r`n"
foreach ($item in $sorted) {
    $output += $item.Link + "`r`n"
}
$output += $footer

$output | Out-File -FilePath "g:\0.CMS-MAIN-ALL -ctt\qunagr binhup pdf\New folder\content.txt" -Encoding UTF8

Write-Host "Sorted $($sorted.Count) links by QT number"
$sorted | Format-Table QTNum, @{N='Name';E={$_.Link -replace '.*QT[.\s]*(\d+).*', 'QT$1'}} -AutoSize

Add-Type -AssemblyName System.Web

$content = Get-Content -Path "g:\0.CMS-MAIN-ALL -ctt\qunagr binhup pdf\New folder\content.txt" -Raw

$lines = $content -split "`r`n|`n"
$header = $lines[0] + "`r`n" + $lines[1]

$footer = ""
for ($i = $lines.Count - 1; $i -ge 0; $i--) {
    if ($lines[$i] -match "</div>") {
        if ($i -eq $lines.Count - 1) {
            $footer = $lines[-2] + "`r`n" + $lines[-1]
        } else {
            $footer = $lines[$i] + "`r`n" + $lines[$i+1]
        }
        break
    }
}

$pattern = '<a href="/Media/quy-trinh/QT[^"]*" style="[^"]*">[^<]*</a>'
$matches = [regex]::Matches($content, $pattern)

$linkObjects = @()
foreach ($m in $matches) {
    $href = $m.Value
    # URL decode to handle %20 etc
    $decoded = [System.Uri]::UnescapeDataString($href)

    $num = 0
    if ($decoded -match 'QT\.\s*(\d+)') {
        $num = [int]$matches[1]
    } elseif ($decoded -match 'QT\s*(\d+)') {
        $num = [int]$matches[1]
    }

    $linkObjects += [PSCustomObject]@{ QTNum = $num; Link = $href }
}

$sorted = $linkObjects | Sort-Object QTNum

$output = $header + "`r`n"
foreach ($item in $sorted) {
    $output += $item.Link + "`r`n"
}
$output += $footer

$output | Out-File -FilePath "g:\0.CMS-MAIN-ALL -ctt\qunagr binhup pdf\New folder\content.txt" -Encoding UTF8

Write-Host "Sorted $($sorted.Count) links by QT number"
$sorted | Format-Table QTNum, @{N='Name';E={$_.Link -replace '.*/([^/]+\.pdf).*', '$1'}} -AutoSize

$content = Get-Content -Path "g:\0.CMS-MAIN-ALL -ctt\qunagr binhup pdf\New folder\content.txt" -Raw

$lines = $content -split "`r`n|`n"

$stt = 0
$newLines = @()
foreach ($line in $lines) {
    if ($line -match '<a href="/Media/quy-trinh/QT') {
        $stt++
        $newLine = $line -replace '">📄 ', '">📄 ' + $stt + '. '
        $newLines += $newLine
    } else {
        $newLines += $line
    }
}

$newLines -join "`r`n" | Out-File -FilePath "g:\0.CMS-MAIN-ALL -ctt\qunagr binhup pdf\New folder\content.txt" -Encoding UTF8

Write-Host "Done! Added STT from 1 to $stt"
